/**
 * `defineConnection` — authored at `agent/mcp-connections/<name>.ts`
 * (model + host) or `agent/host-connections/<name>.ts` (host + `mcp oauth`
 * only).
 *
 * A connection gives tools from an external MCP server. The filename
 * becomes the connection (server) name. Files under `mcp-connections/`
 * are available to the agent (SDK `mcpServers`), host (`ctx.host.mcp`),
 * and channel/schedule handlers. Pass `advertiseTools: true` for named
 * tools on local turns. Pass `effects: "read"` with `advertiseTools` to
 * advertise only tools the server classifies as reads. Pass `tools` as
 * a name list to keep a subset, same shape as `defineAgent({ tools })`.
 * Pass `disallowedTools` to drop names. Files under
 * `host-connections/` stay off the model.
 *
 * ```ts
 * import { defineConnection } from "@grok/agent-sdk/connections";
 *
 * export default defineConnection({
 *   url: "https://mcp.linear.app/mcp",
 *   headers: { authorization: "Bearer ${LINEAR_TOKEN}" },
 * });
 *
 * // TypeScript tools, packaged as stdio MCP for the agent environment:
 * export default defineConnection({
 *   tools: {
 *     probe_cloud_tool: {
 *       description: "Prove the tool ran in the agent environment.",
 *       async execute({ label }) {
 *         return { ok: true, label };
 *       },
 *     },
 *   },
 * });
 *
 * export default defineConnection({
 *   cursorAccount: true,
 *   servers: ["anytool"],
 * });
 *
 * // query-only: advertise only tools classified as reads
 * export default defineConnection({
 *   url: "https://api.cursor.com/v1/agent/mcp",
 *   advertiseTools: true,
 *   effects: "read",
 * });
 *
 * // named subset: advertise and call only these tools
 * export default defineConnection({
 *   url: "https://mcp.example.com/inventory",
 *   advertiseTools: true,
 *   tools: ["search_skus", "get_stock"],
 * });
 *
 * // drop a few tools from a large server
 * export default defineConnection({
 *   url: "https://mcp.example.com/inventory",
 *   advertiseTools: true,
 *   disallowedTools: ["place_order", "delete_sku"],
 * });
 * ```
 *
 * A **Cursor account MCP connection** exposes the MCP connectors the operator
 * already authorized in their Cursor account (dashboard → MCP). Every tool
 * executes **on the Cursor backend** with the account's stored OAuth
 * credentials, so the agent gets Linear / Notion / Slack / … tools with
 * zero token plumbing and no OAuth secrets on this host. Requires the host
 * to be signed in (`agent-sdk login`, `CURSOR_API_KEY`, or
 * `CURSOR_SERVICE_ACCOUNT_KEY`):
 *
 * ```ts
 * // agent/mcp-connections/account.ts — every connected server (no allowlist)
 * export default defineConnection({
 *   cursorAccount: true,
 *   advertiseTools: true,
 * });
 * // equivalent explicit form:
 * export default defineConnection({
 *   cursorAccount: true,
 *   servers: "*",
 *   advertiseTools: true,
 * });
 *
 * // or restrict to specific connectors by name
 * export default defineConnection({
 *   cursorAccount: true,
 *   servers: ["Linear"],
 *   advertiseTools: true,
 * });
 * ```
 *
 * A **peer MCP connection** addresses another agent mounted on the same serve
 * host by slug — every mounted agent is itself an MCP server at
 * `/<slug>/v1/mcp` (tools: `ask`, `check`, and `call_tool` when it has
 * server tools), so the model can delegate work to the peer, which runs
 * in its own sessions with its own tools and context:
 *
 * ```ts
 * export default defineConnection({
 *   agent: "weather-agent",
 *   description: "Delegate weather questions to the weather agent.",
 * });
 * ```
 *
 * Peer URLs resolve over loopback when the server starts.
 *
 * Server tools can call the same connection:
 *
 * ```ts
 * async execute(input, ctx) {
 *   return ctx.host.mcp.callTool("linear", "list_issues", { query: input.q });
 * }
 * ```
 *
 * So can webhook / channel route handlers (deterministic, no agent loop):
 *
 * ```ts
 * POST("/sync", {
 *   bodySchema: z.object({}),
 *   handler: async (_req, { host }) => {
 *     const result = await host.mcp.callTool("linear", "list_issues", {});
 *     return Response.json(result);
 *   },
 * });
 * ```
 */
import { createRequire } from "node:module";
import { brandDefinition } from "./internal/brand.js";
export { isInlineStdioConnection, isToolEffect, normalizeConnectionEffects, normalizeConnectionTools, normalizeCursorAccountServers, } from "./types.js";
export function defineConnection(config) {
    return brandDefinition("connection", config);
}
const SLACK_BOT_ENABLED_TOOLS = [
    "conversations_history",
    "conversations_replies",
    "attachment_get_data",
];
const SLACK_BOT_STDIO_FLAGS = ["--transport", "stdio", "--no-cache"];
const ENV_NAME = /^[A-Za-z_][A-Za-z0-9_]*$/;
function slackBotTokenTemplate(tokenEnv) {
    if (!ENV_NAME.test(tokenEnv)) {
        throw new Error(`slackBotConnection tokenEnv must be an environment variable name, received ${JSON.stringify(tokenEnv)}`);
    }
    return `\${${tokenEnv}}`;
}
function slackBotStdio(launch) {
    switch (launch.kind) {
        case "path":
            return { command: "slack-mcp-server", args: [...SLACK_BOT_STDIO_FLAGS] };
        case "resolved":
            return {
                command: process.execPath,
                args: [createRequire(launch.from).resolve("slack-mcp-server"), ...SLACK_BOT_STDIO_FLAGS],
            };
        default: {
            const _exhaustive = launch;
            throw new Error(`Unknown Slack bot launch: ${JSON.stringify(_exhaustive)}`);
        }
    }
}
/**
 * Read-only stdio connection to `slack-mcp-server` for one bot token.
 *
 * The enabled-tool list is the model's whole catalog for this server.
 * Mutating tools stay out even if the server enables more by default, and
 * the message tool stays off because this helper never sets
 * `SLACK_MCP_ADD_MESSAGE_TOOL`. `--no-cache` disables channel-name lookup;
 * callers pass channel IDs. The token stays a `${NAME}` template and is
 * read when the connection opens, not when this module loads.
 */
export function slackBotConnection(args) {
    const stdio = slackBotStdio(args.launch);
    return defineConnection({
        command: stdio.command,
        args: stdio.args,
        env: {
            SLACK_MCP_XOXB_TOKEN: slackBotTokenTemplate(args.tokenEnv),
            SLACK_MCP_ENABLED_TOOLS: SLACK_BOT_ENABLED_TOOLS.join(","),
            SLACK_MCP_LOG_LEVEL: "warn",
        },
        advertiseTools: true,
        optional: args.optional,
        description: args.description,
    });
}
